INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das YAGNI-Prinzip nur für kleine Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch große Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem YAGNI-Prinzip?', 3, '[{"text": "Überflüssige Features vermeiden", "correct": true, "because": "Fokus auf aktuelle Bedürfnisse"}, {"text": "Code schneller machen", "correct": false, "because": "Nicht primär"}, {"text": "Maximale Funktionalität", "correct": false, "because": "Widerspricht YAGNI"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das YAGNI-Prinzip?', 5, '[{"text": "Weniger Aufwand", "correct": true, "because": "Nur Nötiges umsetzen"}, {"text": "Einfacherer Code", "correct": true, "because": "Keine unnötige Komplexität"}, {"text": "Höhere Performance", "correct": false, "because": "Nicht garantiert"}, {"text": "Mehr Features", "correct": false, "because": "Widerspricht YAGNI"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) YAGNI fokussiert aktuelle Anforderungen. b) Es verbietet zukünftige Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Planung erlaubt, wenn nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim YAGNI-Prinzip?', 4, '[{"text": "Aktuelle Bedürfnisse", "correct": false, "because": "Kern des Prinzips"}, {"text": "Einfachheit", "correct": false, "because": "Fördert YAGNI"}, {"text": "Zukünftige Features", "correct": true, "because": "Nur bei Bedarf umsetzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob YAGNI Vorplanung verbietet?', 2, '[{"text": "Nein", "correct": true, "because": "Nur unnötige Umsetzung vermeiden"}, {"text": "Ja", "correct": false, "because": "Planung erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel folgt dem YAGNI-Prinzip?', 3, '[{"text": "Nur aktuelle Funktion coden", "correct": true, "because": "Keine Überplanung"}, {"text": "Komplexes Framework für Zukunft", "correct": false, "because": "Unnötig jetzt"}, {"text": "Alle Features vorab", "correct": false, "because": "Widerspricht YAGNI"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördert das YAGNI-Prinzip?', 5, '[{"text": "Kosteneffizienz", "correct": true, "because": "Weniger unnötiger Aufwand"}, {"text": "Klarheit", "correct": true, "because": "Fokus auf Jetzt"}, {"text": "Maximale Abstraktion", "correct": false, "because": "Nur wenn nötig"}, {"text": "Hoher Speicherbedarf", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) YAGNI spart Zeit. b) Es macht Code unflexibel. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität bleibt möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das YAGNI-Prinzip?', 4, '[{"text": "Fokus auf Anforderungen", "correct": false, "because": "Zentrales Element"}, {"text": "Einfachheit", "correct": false, "because": "Fördert YAGNI"}, {"text": "Zukunftsfeatures", "correct": true, "because": "Nur bei Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist YAGNI ohne Anforderungen möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungen definieren Umfang"}, {"text": "Ja", "correct": false, "because": "Basis nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst das YAGNI-Prinzip?', 4, '[{"text": "Überentwicklung", "correct": true, "because": "Nur Nötiges umsetzen"}, {"text": "Komplexität", "correct": true, "because": "Weniger unnötiger Code"}, {"text": "Langsame Tests", "correct": false, "because": "Kein Testfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass YAGNI nur für Prototypen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Produktion nützlich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim YAGNI-Prinzip?', 3, '[{"text": "Aktuelle Bedürfnisse", "correct": true, "because": "Nur Nötiges jetzt"}, {"text": "Zukünftige Erweiterung", "correct": false, "because": "Widerspricht YAGNI"}, {"text": "Viele Features", "correct": false, "because": "Unnötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) YAGNI reduziert Aufwand. b) Es verbietet Erweiterbarkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erweiterbarkeit bleibt möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das YAGNI-Prinzip?', 5, '[{"text": "Fehlende Vorplanung", "correct": true, "because": "Zukunft kann schwieriger sein"}, {"text": "Eingeschränkte Features", "correct": true, "because": "Nur aktuelles umgesetzt"}, {"text": "Langsamere Ausführung", "correct": false, "because": "Kein Performance-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim YAGNI-Prinzip unwichtig?', 3, '[{"text": "Aktuelle Anforderungen", "correct": false, "because": "Kernprinzip"}, {"text": "Einfachheit", "correct": false, "because": "Fördert YAGNI"}, {"text": "Zukünftige Spekulation", "correct": true, "because": "Soll vermieden werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Macht YAGNI Code immer einfacher?', 3, '[{"text": "Ja", "correct": true, "because": "Weniger unnötige Komplexität"}, {"text": "Nein", "correct": false, "because": "Einfachheit ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob YAGNI Refactoring erschwert?', 2, '[{"text": "Nein", "correct": true, "because": "Einfacher Code leichter anpassbar"}, {"text": "Ja", "correct": false, "because": "Weniger Vorarbeit hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ergänzt das YAGNI-Prinzip?', 4, '[{"text": "KISS", "correct": true, "because": "Einfachheit unterstützt"}, {"text": "DRY", "correct": false, "because": "Wiederverwendungs-Fokus"}, {"text": "OCP", "correct": false, "because": "Erweiterungs-Fokus"}]');
